-- API-41 지역 검색. regions는 행정안전부 법정동코드 데이터를 정적으로 시딩한
-- 조회용 카탈로그라, 사용자 입력으로 바뀌지 않는다(행정 경계 개편 시에만 갱신).
--
-- region_id는 내부 자체 IDENTITY 대신 법정동코드 수치를 그대로 쓴다: 코드 앞자리가
-- 이미 상위 지역을 나타내는 계층 구조라(예: 11110=서울 종로구는 11=서울 아래),
-- 별도 lookup 없이 코드만으로 parent_region_id 계산/검증이 가능해진다.
--   SIDO    : 2자리 시도코드 * 1000 (예: 서울 11 -> 11000)
--   SIGUNGU : 5자리 시군구코드 그대로 (예: 종로구 11110)
--   DONG    : 10자리 법정동코드 원본 그대로
CREATE TABLE regions (
    region_id BIGINT PRIMARY KEY,
    name VARCHAR(50) NOT NULL,
    full_name VARCHAR(100) NOT NULL,
    level VARCHAR(10) NOT NULL CHECK (level IN ('SIDO', 'SIGUNGU', 'DONG')),
    parent_region_id BIGINT REFERENCES regions(region_id)
);

CREATE INDEX idx_regions_level_name ON regions(level, name);
CREATE INDEX idx_regions_parent ON regions(parent_region_id);

-- 아래 시드 데이터 출처: 행정안전부 법정동코드 전체자료 2022-08 스냅샷
-- (https://gist.github.com/cokia/9dcde3540ef7a93e7134f084ee46bedb). 행정 경계는
-- 거의 바뀌지 않으므로(팀 결정, 2026-11-04) 이 시점 스냅샷으로 시딩한다.
-- SIDO 17행 + SIGUNGU 250행 + DONG(읍면동) 5,054행 = 총 5,321행.
-- API-41 지역 검색: 행정안전부 법정동코드(2022-08 스냅샷) 기반 regions 시드 데이터.
-- region_id는 법정동코드 그대로 쓴다: SIDO는 (2자리 시도코드*1000), SIGUNGU는 5자리 시군구코드, DONG은 10자리 법정동코드 원본.
-- 법정동코드 수치 자체가 계층을 그대로 표현하기 때문에(앞자리가 상위 코드), 내부 자체 ID를 새로 발급하는 대신 이 값을 region_id로 직접 쓴다.

